import asyncio,os,json
from urllib.parse import urlencode
from websockets.asyncio.client import connect
async def main():
 p={'sample_rate':16000,'speech_model':'universal-streaming-english','domain':'medical-v1','speaker_labels':'true','redact_pii':'true','format_turns':'true','redact_pii_sub':'entity_name'}
 try:
  async with connect('wss://streaming.assemblyai.com/v3/ws?'+urlencode(p),additional_headers={'Authorization':os.environ['ASSEMBLYAI_API_KEY']},open_timeout=20) as ws:
   for i in range(3):
    try:
     m=await asyncio.wait_for(ws.recv(),3); print(m)
     if json.loads(m).get('type')=='Begin': await ws.send(json.dumps({'type':'Terminate'}))
    except asyncio.TimeoutError: break
 except Exception as e: print(type(e).__name__,str(e))
asyncio.run(main())
PY"

